import React, { useRef, useEffect } from 'react';

export default function MeshSphere({ size = 300, speed = 0.4, distort = 0.5 }) {
  const canvasRef = useRef(null);
  const raf = useRef(null);
  const t = useRef(0);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    canvas.width  = size;
    canvas.height = size;
    const ctx = canvas.getContext('2d');
    const cx = size / 2, cy = size / 2;

    // Palette — shifts between deep blue/indigo and moss/sage
    // distort 0 = calm, pure blue-green
    // distort 1 = slightly warmer, more indigo
    const getCol = () => {
      const s    = t.current * 0.03 * speed;
      const mood = distort;

      // Core: deep blue → indigo → moss, depending on mood
      const h1 = 200 + mood * 30  + Math.sin(s * 0.6) * 8;   // steel blue to indigo
      const h2 = 185 + mood * 40  + Math.cos(s * 0.5) * 6;   // teal to blue
      const h3 = 165 + mood * 50  + Math.sin(s * 0.4) * 8;   // moss to indigo

      return { h1, h2, h3 };
    };

    const draw = () => {
      t.current += 0.007 * speed;
      ctx.clearRect(0, 0, size, size);

      const { h1, h2, h3 } = getCol();
      const pulse = 1 + Math.sin(t.current * 0.45) * 0.035;

      // ── 1. Outer feathered glow ─────────────────────────────
      const g1 = ctx.createRadialGradient(cx, cy, 0, cx, cy, size * 0.50 * pulse);
      g1.addColorStop(0,    `hsla(${h2}, 40%, 52%, 0.20)`);
      g1.addColorStop(0.40, `hsla(${h1}, 38%, 55%, 0.13)`);
      g1.addColorStop(0.70, `hsla(${h3}, 32%, 60%, 0.06)`);
      g1.addColorStop(1,    'transparent');
      ctx.fillStyle = g1;
      ctx.fillRect(0, 0, size, size);

      // ── 2. Rich core ────────────────────────────────────────
      const ox = Math.sin(t.current * 0.28) * size * 0.022;
      const oy = Math.cos(t.current * 0.22) * size * 0.018;
      const g2 = ctx.createRadialGradient(cx+ox, cy+oy, 0, cx+ox, cy+oy, size * 0.34 * pulse);
      g2.addColorStop(0,    `hsla(${h2 + 10}, 42%, 62%, 0.82)`);
      g2.addColorStop(0.28, `hsla(${h1},      44%, 50%, 0.72)`);
      g2.addColorStop(0.58, `hsla(${h3},      38%, 48%, 0.48)`);
      g2.addColorStop(0.85, `hsla(${h3 - 10}, 32%, 55%, 0.20)`);
      g2.addColorStop(1,    'transparent');
      ctx.fillStyle = g2;
      ctx.fillRect(0, 0, size, size);

      // ── 3. Secondary blob — moss/sage accent ───────────────
      const ox2 = -Math.sin(t.current * 0.24) * size * 0.038;
      const oy2 = -Math.cos(t.current * 0.20) * size * 0.030;
      const g3  = ctx.createRadialGradient(cx+ox2, cy+oy2, 0, cx+ox2, cy+oy2, size * 0.27 * pulse);
      g3.addColorStop(0,    `hsla(${h3 + 5}, 36%, 55%, 0.62)`);
      g3.addColorStop(0.45, `hsla(${h3},     32%, 58%, 0.32)`);
      g3.addColorStop(1,    'transparent');
      ctx.fillStyle = g3;
      ctx.fillRect(0, 0, size, size);

      // ── 4. Ring layer — depth and dimension ────────────────
      const ox3 = Math.cos(t.current * 0.17) * size * 0.012;
      const oy3 = Math.sin(t.current * 0.20) * size * 0.010;
      const g4  = ctx.createRadialGradient(cx+ox3, cy+oy3, size*0.09*pulse, cx+ox3, cy+oy3, size*0.37*pulse);
      g4.addColorStop(0,    `hsla(${h2 + 20}, 50%, 78%, 0.28)`);
      g4.addColorStop(0.30, `hsla(${h1 + 10}, 46%, 58%, 0.52)`);
      g4.addColorStop(0.58, `hsla(${h1},      42%, 50%, 0.40)`);
      g4.addColorStop(0.82, `hsla(${h3},      36%, 52%, 0.18)`);
      g4.addColorStop(1,    'transparent');
      ctx.fillStyle = g4;
      ctx.fillRect(0, 0, size, size);

      // ── 5. Soft offwhite centre glow ────────────────────────
      const g5 = ctx.createRadialGradient(cx+ox*0.4, cy+oy*0.4, 0, cx, cy, size * 0.16 * pulse);
      g5.addColorStop(0,    `hsla(${h2 + 30}, 30%, 88%, 0.55)`);
      g5.addColorStop(0.50, `hsla(${h2 + 20}, 28%, 82%, 0.20)`);
      g5.addColorStop(1,    'transparent');
      ctx.fillStyle = g5;
      ctx.fillRect(0, 0, size, size);

      raf.current = requestAnimationFrame(draw);
    };

    draw();
    return () => cancelAnimationFrame(raf.current);
  }, [size, speed, distort]);

  return (
    <canvas ref={canvasRef} style={{ display:'block', width:`${size}px`, height:`${size}px` }} />
  );
}
